SELECT id, title, intro as description, link as productUrl, status, create_time as createTime, update_time as updateTime, view_cnt as viewCount, cart_add_cnt as cartCount FROM spu WHERE 1=1
AND title LIKE CONCAT('%', #{title}, '%')
AND status = #{status}
ORDER BY create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM spu WHERE 1=1
AND title LIKE CONCAT('%', #{title}, '%')
AND status = #{status}
